# Author / creator / last modified by: Chunhao Guo
# Locked B1/B2 operator contract v1, 2026-11-13.
# All functions: expression is numeric genes x samples, unique rownames, declared
# released log scale; gene_set is the COMPLETE requested set. ref_idx indexes
# training samples; reference reuses returned parameters (and overrides ref_idx).
# Returns scores (also score), raw, per-sample available, reason, reference.
# Missing genes are never dropped or imputed. Invalid reference => all unavailable.
# O4-O6 require whole_transcriptome=TRUE: caller certifies full released universe.
# O1/O2/O3/O7 aggregate scaling uses reference mean and SAMPLE SD.
.op_fail <- function(x, reason) {v<-setNames(rep(NA_real_,ncol(x)),colnames(x));list(scores=v,score=v,raw=v,available=rep(FALSE,ncol(x)),reason=reason,reference=NULL)}
.op_check <- function(x,g,idx) {if(!is.matrix(x)||!is.numeric(x)||is.null(rownames(x))||anyDuplicated(rownames(x)))return('expression must be numeric with unique gene names');if(!length(g)||anyDuplicated(g)||!all(g%in%rownames(x)))return(paste('missing or duplicated signature genes:',paste(setdiff(g,rownames(x)),collapse=';')));if(!length(idx)||anyNA(idx)||any(idx<1|idx>ncol(x)))return('invalid reference indices');NULL}
.op_finish <- function(x,raw,idx,reference=NULL,params=list(),scale=TRUE) {if(scale){if(is.null(reference)){center<-mean(raw[idx]);unit<-sd(raw[idx])}else{center<-reference$center;unit<-reference$unit};if(!is.finite(unit)||unit<=1e-8||!is.finite(center))return(.op_fail(x,'invalid aggregate reference SD'));scores<-(raw-center)/unit;params$center<-center;params$unit<-unit}else scores<-raw;names(scores)<-names(raw)<-colnames(x);list(scores=scores,score=scores,raw=raw,available=is.finite(scores),reason=if(all(is.finite(scores)))'available' else 'nonfinite sample expression',reference=params)}
# O1: mean-expression score, aggregate reference-standardised (= I0).
O1 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));.op_finish(x,colMeans(x[gene_set,,drop=FALSE]),ref_idx,reference)}
# O2: gene reference mean/SD, arithmetic mean, aggregate scaling (= I1).
O2 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));m<-x[gene_set,,drop=FALSE];mu<-if(is.null(reference))rowMeans(m[,ref_idx,drop=FALSE]) else reference$gene_center;ss<-if(is.null(reference))apply(m[,ref_idx,drop=FALSE],1,sd) else reference$gene_scale;if(any(!is.finite(ss)|ss<=1e-8)||any(!is.finite(mu)))return(.op_fail(x,'required gene reference SD <= 1e-8 or nonfinite'));raw<-colMeans(sweep(sweep(m,1,mu,'-'),1,ss,'/'));.op_finish(x,raw,ref_idx,reference,list(gene_center=mu,gene_scale=ss))}
# O3: reference median / (1.4826 * unscaled MAD), then mean and aggregate scaling.
O3 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));m<-x[gene_set,,drop=FALSE];mu<-if(is.null(reference))apply(m[,ref_idx,drop=FALSE],1,median) else reference$gene_center;mm<-if(is.null(reference))apply(m[,ref_idx,drop=FALSE],1,mad,constant=1) else reference$gene_MAD;if(any(!is.finite(mm)|mm<=1e-8)||any(!is.finite(mu)))return(.op_fail(x,'required gene reference MAD <= 1e-8 or nonfinite'));ss<-1.4826*mm;raw<-colMeans(sweep(sweep(m,1,mu,'-'),1,ss,'/'));.op_finish(x,raw,ref_idx,reference,list(gene_center=mu,gene_MAD=mm,gene_scale=ss))}
# O4: Foroutan up-only centred singscore, minimum tied ranks; untied range [-0.5,0.5].
# Exact fallback: (mean(rank_up)-(k+1)/2)/(N-k)-0.5, verified by selftest.
# No gene-variance filtering; all released genes participate in each sample rank.
O4 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,whole_transcriptome=FALSE,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));if(!whole_transcriptome)return(.op_fail(x,'full released gene universe not certified'));if(any(!is.finite(x)))return(.op_fail(x,'nonfinite whole-transcriptome matrix'));N<-nrow(x);k<-length(gene_set);if(k>=N)return(.op_fail(x,'signature exhausts ranking universe'));if(requireNamespace('singscore',quietly=TRUE)){r<-singscore::rankGenes(x);raw<-singscore::simpleScore(r,upSet=gene_set,centerScore=TRUE,knownDirection=TRUE)$TotalScore;engine<-'singscore::simpleScore'}else{ii<-match(gene_set,rownames(x));raw<-vapply(seq_len(ncol(x)),function(j)(mean(rank(x[,j],ties.method='min')[ii])-(k+1)/2)/(N-k)-.5,numeric(1));engine<-'published exact formula'};.op_finish(x,raw,ref_idx,scale=FALSE,params=list(engine=engine,universe=rownames(x)))}
# O5: GSVA ssGSEA alpha=.25, normalize=FALSE. Frozen per-sample form.
O5 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,whole_transcriptome=FALSE,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));if(!whole_transcriptome)return(.op_fail(x,'full released gene universe not certified'));if(!requireNamespace('GSVA',quietly=TRUE))return(.op_fail(x,'GSVA package unavailable'));if(any(!is.finite(x)))return(.op_fail(x,'nonfinite whole-transcriptome matrix'));p<-GSVA::ssgseaParam(x,list(signature=gene_set),minSize=length(gene_set),maxSize=length(gene_set),alpha=.25,normalize=FALSE);raw<-tryCatch(as.numeric(GSVA::gsva(p,verbose=FALSE,BPPARAM=BiocParallel::SerialParam())),error=function(e)e);if(inherits(raw,'error')||length(raw)!=ncol(x))return(.op_fail(x,if(inherits(raw,'error'))conditionMessage(raw) else 'ssGSEA score size mismatch'));.op_finish(x,raw,ref_idx,scale=FALSE,params=list(engine='GSVA ssGSEA',alpha=.25,normalize=FALSE,universe=rownames(x)))}
# O6: cohort-dependent GSVA, Gaussian kernel, package default tau=1.
# No frozen form: reference parameters are intentionally rejected.
O6 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,whole_transcriptome=FALSE,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));if(!whole_transcriptome)return(.op_fail(x,'full released gene universe not certified'));if(!is.null(reference)||!identical(as.integer(ref_idx),seq_len(ncol(x))))return(.op_fail(x,'GSVA has no frozen single-patient form'));if(!requireNamespace('GSVA',quietly=TRUE))return(.op_fail(x,'GSVA package unavailable'));if(any(!is.finite(x)))return(.op_fail(x,'nonfinite whole-transcriptome matrix'));p<-GSVA::gsvaParam(x,list(signature=gene_set),minSize=length(gene_set),maxSize=length(gene_set),kcdf='Gaussian',tau=1,filterRows=FALSE);raw<-tryCatch(as.numeric(GSVA::gsva(p,verbose=FALSE,BPPARAM=BiocParallel::SerialParam())),error=function(e)e);if(inherits(raw,'error')||length(raw)!=ncol(x))return(.op_fail(x,if(inherits(raw,'error'))conditionMessage(raw) else 'GSVA score size mismatch'));.op_finish(x,raw,ref_idx,scale=FALSE,params=list(engine='GSVA',kcdf='Gaussian',tau=1,filterRows=FALSE,universe=rownames(x)))}
# O7: PC1 on reference gene-standardised signature, sign positive against O1.
# PC uses prcomp center=FALSE scale.=FALSE after explicit reference z scoring.
O7 <- function(expression,gene_set,ref_idx=seq_len(ncol(expression)),reference=NULL,...) {x<-expression;bad<-.op_check(x,gene_set,ref_idx);if(!is.null(bad))return(.op_fail(x,bad));m<-x[gene_set,,drop=FALSE];mu<-if(is.null(reference))rowMeans(m[,ref_idx,drop=FALSE]) else reference$gene_center;ss<-if(is.null(reference))apply(m[,ref_idx,drop=FALSE],1,sd) else reference$gene_scale;if(any(!is.finite(ss)|ss<=1e-8)||any(!is.finite(mu)))return(.op_fail(x,'required gene reference SD <= 1e-8 or nonfinite'));z<-sweep(sweep(m,1,mu,'-'),1,ss,'/');if(any(!is.finite(z)))return(.op_fail(x,'nonfinite signature expression'));if(is.null(reference)){loading<-prcomp(t(z[,ref_idx,drop=FALSE]),center=FALSE,scale.=FALSE,rank.=1)$rotation[,1];r<-cor(as.numeric(crossprod(loading,z[,ref_idx,drop=FALSE])),colMeans(m[,ref_idx,drop=FALSE]));if(!is.finite(r)||abs(r)<1e-12)return(.op_fail(x,'PC1 sign cannot be oriented against O1'));loading<-loading*sign(r)}else loading<-reference$loading;raw<-as.numeric(crossprod(loading,z));.op_finish(x,raw,ref_idx,reference,list(gene_center=mu,gene_scale=ss,loading=loading))}
